  function chip(i) { return `<span class="chip" ${i.entity?`data-entity="${esc(i.entity)}"`:''}>${i.icon?icon(i.icon):''}${i.value?`<b>${esc(i.value)}</b>`:''}${esc(i.label)}</span>`; }
